import os
import io
from typing import Any, Dict, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _read_document_bytes(document: Union[str, bytes, bytearray, io.BufferedIOBase]) -> bytes:
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)
    if hasattr(document, "read"):
        data = document.read()
        if isinstance(data, str):
            return data.encode("utf-8")
        return data
    if isinstance(document, str):
        with open(document, "rb") as f:
            return f.read()
    raise TypeError("document must be a file path, bytes, bytearray, or file-like object")


def extract_key_value_pairs(
    document: Union[str, bytes, bytearray, io.BufferedIOBase],
    region_name: str = None,
) -> Dict[str, Any]:
    """
    Extract key-value pairs from a form-like document using Amazon Textract.

    Returns a dictionary with:
      - key_value_pairs: list of {"key": ..., "value": ..., "confidence": ...}
      - fields: dictionary mapping normalized keys to values
      - raw_blocks: full Textract blocks response
    """
    textract = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION"))

    document_bytes = _read_document_bytes(document)

    try:
        response = textract.analyze_document(
            Document={"Bytes": document_bytes},
            FeatureTypes=["FORMS"],
        )
    except (BotoCoreError, ClientError):
        raise

    blocks = response.get("Blocks", [])
    blocks_by_id = {block["Id"]: block for block in blocks if "Id" in block}

    key_map = {}
    value_map = {}
    for block in blocks:
        block_type = block.get("BlockType")
        if block_type == "KEY_VALUE_SET":
            entity_types = block.get("EntityTypes", [])
            if "KEY" in entity_types:
                key_map[block["Id"]] = block
            elif "VALUE" in entity_types:
                value_map[block["Id"]] = block

    def _extract_text_from_block(block: Dict[str, Any]) -> str:
        text_parts = []
        for rel in block.get("Relationships", []):
            if rel.get("Type") == "CHILD":
                for child_id in rel.get("Ids", []):
                    child = blocks_by_id.get(child_id)
                    if not child:
                        continue
                    if child.get("BlockType") == "WORD":
                        text_parts.append(child.get("Text", ""))
                    elif child.get("BlockType") == "SELECTION_ELEMENT" and child.get("SelectionStatus") == "SELECTED":
                        text_parts.append("X")
        return " ".join(part for part in text_parts if part).strip()

    key_value_pairs = []
    normalized_fields = {}

    for key_id, key_block in key_map.items():
        key_text = _extract_text_from_block(key_block)
        value_text = ""
        confidence = key_block.get("Confidence", None)

        for rel in key_block.get("Relationships", []):
            if rel.get("Type") == "VALUE":
                for value_id in rel.get("Ids", []):
                    value_block = value_map.get(value_id)
                    if value_block:
                        value_text = _extract_text_from_block(value_block)
                        confidence = min(confidence, value_block.get("Confidence", confidence)) if confidence is not None else value_block.get("Confidence", None)

        key_value_pairs.append(
            {
                "key": key_text,
                "value": value_text,
                "confidence": confidence,
            }
        )

        if key_text:
            normalized_fields[key_text] = value_text

    return {
        "key_value_pairs": key_value_pairs,
        "fields": normalized_fields,
        "raw_blocks": response,
    }
